-- 4) Completar mapeo a ev_lugar_mst (columna ev_ri-ev_lu_id-fk)
UPDATE `ev_riesgo_cfg` e
LEFT JOIN `ev_lugar_mst` l_by_id ON l_by_id.`ev_lu-id` = e.`ev_ri-el_vu_id-fk`
LEFT JOIN `ev_lugar_mst` l_by_cod ON UPPER(TRIM(l_by_cod.`ev_lu-cod`)) = UPPER(TRIM(e.`ev_ri-el_vu_cod-fk`))
SET e.`ev_ri-ev_lu_id-fk` = COALESCE(l_by_id.`ev_lu-id`, l_by_cod.`ev_lu-id`);

SET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;
COMMIT;

-- Verificación rápida
SELECT 'riesgo_sub1_cat' AS tabla, COUNT(*) AS total FROM `riesgo_sub1_cat`
UNION ALL SELECT 'riesgo_sub2_cat', COUNT(*) FROM `riesgo_sub2_cat`
UNION ALL SELECT 'ev_riesgo_cfg', COUNT(*) FROM `ev_riesgo_cfg`;
